// Elyndra's visual grammar: feather, ribbon, rune and crystal. No combat rules live here.
const TAU=Math.PI*2,clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
let assets={};const tints=new Map();
export function setFantasyAssets(value){assets=value;tints.clear();}
export const FANTASY_STYLES=[
 {id:'blackhole',name:'Véu Primordial',short:'Véu Primordial',theme:'veil',color:'#bf8cff',secondary:'#ffd58a',price:0,description:'Fitas de mana violeta sobem pelos lados do corpo, com centelhas douradas e véu translúcido.'},
 {id:'quasar',name:'Fulgor Serafim',short:'Fulgor Serafim',theme:'seraph',color:'#72edff',secondary:'#b7a2ff',price:45000,description:'Plumas de luz ciano e correntes de energia ascendentes, com brilho prismático nas bordas.'},
 {id:'supernova',name:'Chama Soberana',short:'Chama Soberana',theme:'flame',color:'#ffba63',secondary:'#ff6eab',price:75000,description:'Chamas douradas contornam a silhueta e se desfazem em faíscas rubras.'},
 {id:'neutron',name:'Prisma Imperial',short:'Prisma Imperial',theme:'prism',color:'#a6c7ff',secondary:'#ef98ff',price:60000,description:'Cristais de luz e fitas índigo envolvem o personagem, com reflexos delicados de ametista.'}
];
export function fantasyProfile(rank,style='blackhole',economy=false){const r=clamp(Math.floor(Number(rank)||0),0,500),p=r/500,d=FANTASY_STYLES.find(d=>d.id===style)||FANTASY_STYLES[0];return{...d,rank:r,stage:Math.min(5,Math.floor(r/100)),strength:r?.18+.72*p:0,radius:28+74*p,height:80+90*p,particles:r?(economy?6:Math.min(24,6+Math.floor(r/25))):0,orbitCount:r?(economy?2:Math.min(6,2+Math.floor(r/100))):0};}
export function enchantProfile(rank){const e=clamp(Number(rank)||0,0,100),stage=e===100?5:e>=75?4:e>=50?3:e>=25?2:e>=5?1:0;return{stage,intensity:e/100,color:['#ffffff','#55ff55','#bc65ed','#ffaa00','#00e8ff','#83fff1'][stage],accent:stage===5?'#e1a1ff':stage>=3?'#ffdf98':'#e9f8ff',motes:stage?Math.min(12,stage*2+2):0};}
export const ENCHANT_STAGES=[
 {threshold:0,halo:0,streams:0,particles:0,emission:0},
 {threshold:5,halo:4,streams:1,particles:4,emission:.24},
 {threshold:25,halo:7,streams:2,particles:8,emission:.48},
 {threshold:50,halo:10,streams:3,particles:12,emission:.65},
 {threshold:75,halo:13,streams:4,particles:16,emission:.82},
 {threshold:100,halo:17,streams:5,particles:22,emission:1}
];
export function glint(g,x,y,size,color,alpha=1){g.save();g.globalAlpha=alpha;g.fillStyle=color;g.beginPath();g.moveTo(x,y-size);g.lineTo(x+size*.22,y-size*.22);g.lineTo(x+size,y);g.lineTo(x+size*.22,y+size*.22);g.lineTo(x,y+size);g.lineTo(x-size*.22,y+size*.22);g.lineTo(x-size,y);g.lineTo(x-size*.22,y-size*.22);g.closePath();g.fill();g.restore();}
function hue(color){const n=parseInt(color.slice(1),16),a=[(n>>16&255)/255,(n>>8&255)/255,(n&255)/255],mx=Math.max(...a),mn=Math.min(...a),d=mx-mn;if(!d)return 180;return ((mx===a[0]?(a[1]-a[2])/d:mx===a[1]?(a[2]-a[0])/d+2:(a[0]-a[1])/d+4)*60+360)%360;}
export function effectTexture(cell,color='#7feaff'){const override=cell===0&&assets.supremeEnergy?assets.supremeEnergy:cell===4?assets.fantasySlash:cell===5?assets.fantasySeal:null,image=override||assets.fantasyEffects;if(!image)return null;const key=cell+color;if(tints.has(key))return tints.get(key);if(typeof document==='undefined')return null;const c=document.createElement('canvas');c.width=c.height=192;const g=c.getContext('2d'),cw=(image.naturalWidth||image.width)/4,ch=(image.naturalHeight||image.height)/2;g.filter='hue-rotate('+(hue(color)-185)+'deg) saturate(1.12)';if(override)g.drawImage(image,0,0,192,192);else{const uv=[[.02,.01,.18,.48],[.215,.125,.283,.31],[.502,.125,.263,.31],[.761,.015,.237,.48],[0,.5,.29,.5],[.25,.5,.25,.5],[.535,.505,.19,.49],[.765,.505,.23,.49]][cell],iw=image.naturalWidth||image.width,ih=image.naturalHeight||image.height;g.drawImage(image,uv[0]*iw,uv[1]*ih,uv[2]*iw,uv[3]*ih,0,0,192,192);}if(tints.size>=40)tints.delete(tints.keys().next().value);tints.set(key,c);return c;}
export function stamp(g,cell,x,y,w,h,angle=0,color='#7feaff',alpha=1){const tex=effectTexture(cell,color);if(!tex)return false;g.save();g.translate(x,y);g.rotate(angle);g.globalAlpha=alpha;g.drawImage(tex,-w/2,-h/2,w,h);g.restore();return true;}
export function samplePolyline(points,q){const lengths=[];let total=0;for(let i=1;i<points.length;i++){const d=Math.hypot(points[i][0]-points[i-1][0],points[i][1]-points[i-1][1]);lengths.push(d);total+=d;}let at=clamp(q,0,1)*total;for(let i=0;i<lengths.length;i++){if(at<=lengths[i]||i===lengths.length-1){const a=points[i],b=points[i+1],f=lengths[i]?at/lengths[i]:0;return{x:a[0]+(b[0]-a[0])*f,y:a[1]+(b[1]-a[1])*f,angle:Math.atan2(b[1]-a[1],b[0]-a[0]),length:total};}at-=lengths[i];}return{x:points[0][0],y:points[0][1],angle:0,length:0};}
export function drawEnchantedEdge(g,points,rank,t,attack=false,classColor=null){
 const p=enchantProfile(rank);if(classColor&&p.stage>=3){p.color=classColor;p.accent=p.stage===5?'#ffe8ac':'#a9edff';}const v=ENCHANT_STAGES[p.stage];if(!p.stage||points.length<2)return;
 const pulse=.88+.12*Math.sin(t*3.2),power=v.emission*pulse;
 g.save();g.globalCompositeOperation='screen';g.lineCap='round';g.lineJoin='round';
 const path=()=>{g.beginPath();points.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));};
 // Three bounded halos remain on the measured weapon path, including curved bows.
 for(let n=3;n>0;n--){g.strokeStyle=p.color;g.globalAlpha=power*(.06+(3-n)*.045);g.lineWidth=v.halo*n*.7;path();g.stroke();}
 g.strokeStyle=p.color;g.globalAlpha=.65+power*.25;g.lineWidth=1.4+p.stage*.3;path();g.stroke();
 g.strokeStyle=p.accent;g.globalAlpha=.50+power*.35;g.lineWidth=.65;path();g.stroke();
 for(let n=0;n<v.streams;n++){g.beginPath();for(let k=0;k<=20;k++){const q=k/20,at=samplePolyline(points,q),normal=at.angle+Math.PI/2,offset=Math.sin(q*12-t*(2+n*.17)+n*1.7)*Math.sin(q*Math.PI)*(1+p.stage*1.35);const x=at.x+Math.cos(normal)*offset,y=at.y+Math.sin(normal)*offset;k?g.lineTo(x,y):g.moveTo(x,y);}g.strokeStyle=n%2?p.accent:p.color;g.lineWidth=n===0?1.8:.9;g.globalAlpha=power*(n===0?.8:.48);g.stroke();}
 // Short travelling plumes are tangent to the blade rather than floating in screen space.
 if(p.stage>=2)for(let n=0;n<(p.stage>=4?3:1);n++){const q=.25+((t*.18+n*.27)%.65),at=samplePolyline(points,q);stamp(g,0,at.x,at.y,14+p.stage*4,Math.max(18,at.length*(p.stage>=4?.65:.43)),at.angle+Math.PI/2,n%2?p.accent:p.color,power*(p.stage===5?.85:.55));}
 for(let n=0;n<v.particles;n++){const q=(t*(.30+p.intensity*.22)+n*.618)%1,at=samplePolyline(points,q),normal=at.angle+Math.PI/2,escape=Math.sin(q*Math.PI)*(2+p.stage*1.8)*Math.sin(n*2.4+t),x=at.x+Math.cos(normal)*escape,y=at.y+Math.sin(normal)*escape-q*p.stage*.7;glint(g,x,y,n%5===0?3.2+p.stage*.5:1.5+p.stage*.15,n%2?p.color:p.accent,Math.sin(q*Math.PI)*power*.9);}
 if(p.stage>=4){const at=samplePolyline(points,.75),len=Math.min(30,at.length*.35);g.strokeStyle=p.accent;g.globalAlpha=power*.55;g.lineWidth=.8;for(const side of [-1,1]){g.beginPath();for(let k=0;k<7;k++){const q=k/6,x=at.x+Math.cos(at.angle)*len*q+Math.sin(at.angle)*Math.sin(q*9+t*5)*side*p.stage*1.2,y=at.y+Math.sin(at.angle)*len*q-Math.cos(at.angle)*Math.sin(q*9+t*5)*side*p.stage*1.2;k?g.lineTo(x,y):g.moveTo(x,y);}g.stroke();}}
 if(p.stage===5){const crest=samplePolyline(points,.88);glint(g,crest.x,crest.y,5+2*Math.sin(t*2.4),p.accent,.8);}
 if(attack){const tip=samplePolyline(points,.9);glint(g,tip.x,tip.y,4+p.stage,p.accent,.8);}g.restore();
}
export function drawFantasyPresence(g,rank,t,front=false,style='blackhole',economy=false){const p=fantasyProfile(rank,style,economy);if(!p.rank)return;const {color,secondary,height,strength:s}=p;g.save();g.globalCompositeOperation='screen';g.lineCap='round';
 const count=economy?2:p.theme==='veil'?Math.min(4,2+p.stage):p.stage>=4?6:p.stage>=2?4:2;
 for(let n=0;n<count;n++){const angle=n*TAU/count+t*.18,depth=Math.sin(angle);if((depth>0)!==front)continue;const side=Math.cos(angle),x=side*p.radius,phase=t*.24+n*.618;
  const ribbonColor=n%2?secondary:color,wind=Math.sin(t*.9+n)*9,tip=x*.65,width=3+p.stage*1.1,gradient=g.createLinearGradient(0,4,0,-height);gradient.addColorStop(0,ribbonColor+'00');gradient.addColorStop(.3,ribbonColor+'88');gradient.addColorStop(.7,ribbonColor+'cc');gradient.addColorStop(1,ribbonColor+'00');g.globalAlpha=s*.75;g.fillStyle=gradient;g.beginPath();g.moveTo(x,3);g.bezierCurveTo(x+wind,-height*.28,-x*.2+Math.cos(t*.8+n)*9,-height*.65,tip,-height);g.bezierCurveTo(-x*.2+Math.cos(t*.8+n)*9+width,-height*.65,x+wind+width,-height*.28,x+width,3);g.closePath();g.fill();
  g.strokeStyle=ribbonColor;g.lineWidth=1.2;g.globalAlpha=s*.65;g.beginPath();g.moveTo(x,3);g.bezierCurveTo(x+Math.sin(t*.9+n)*9,-height*.28,-x*.2+Math.cos(t*.8+n)*9,-height*.65,x*.65,-height);g.stroke();
  stamp(g,p.theme==='flame'?0:6,x*.65,-height*.47,16+p.stage*3,height*.95,side*.20,color,s*(p.theme==='flame'?.52:.4));if(p.theme==='seraph'&&p.stage>=2)stamp(g,0,x*.75,-height*.60,8+p.stage,height*.63,-side*.32,secondary,s*.22);
  for(let k=0;k<(economy?2:4);k++){const q=(phase+k*.25)%1,xx=x*(1-q*.25)+Math.sin(q*6+t+n)*3,yy=3-q*height;if(p.theme==='prism'&&k%2===0){g.globalAlpha=Math.sin(q*Math.PI)*s*.75;g.fillStyle=n%2?color:secondary;g.beginPath();g.moveTo(xx,yy-3);g.lineTo(xx+1.5,yy);g.lineTo(xx,yy+4);g.lineTo(xx-1.5,yy);g.closePath();g.fill();}else glint(g,xx,yy,1.1+p.stage*.12,k%2?color:secondary,Math.sin(q*Math.PI)*s*.7);}
 }
 if(p.stage>=3){g.globalAlpha=s*.22;g.strokeStyle=secondary;g.lineWidth=1;g.beginPath();g.ellipse(0,4,p.radius*1.15,p.radius*.38,0,front?0:Math.PI,front?Math.PI:TAU);g.stroke();}g.restore();}
export function drawAuraSeal(g,rank,styleColor,t){const r=clamp(Number(rank)||0,0,500);if(!r)return;const stage=Math.min(5,Math.floor(r/100)),radius=27+r*.045,color=stage===0?'#e9efff':styleColor,alpha=.38+stage*.055;g.save();g.translate(0,4);g.scale(1,.38);g.rotate(t*.042);g.globalCompositeOperation='screen';stamp(g,5,0,0,radius*2.45,radius*2.45,0,color,alpha);g.strokeStyle=color;g.lineWidth=.8;g.globalAlpha=.38;g.beginPath();g.arc(0,0,radius*.72,0,TAU);g.stroke();for(let n=0;n<4+stage;n++){const a=n*TAU/(4+stage)-t*.025;glint(g,Math.cos(a)*radius,Math.sin(a)*radius,1.8,color,.45+.15*Math.sin(t+n));}g.restore();}
export function wingProfile(rank){const r=clamp(Number(rank)||0,0,500),stage=Math.min(5,Math.floor(r/100));return{rank:r,stage,width:112+stage*12,height:91+stage*10,flap:.018+stage*.002,glints:2+stage};}
export function drawFeatherWings(g,rank,t,accent='#8fefff'){const p=wingProfile(rank),im=assets.featherWings;if(!p.rank||!im)return false;const cw=(im.naturalWidth||im.width)/3,ch=(im.naturalHeight||im.height)/2,sx=(p.stage%3)*cw,sy=Math.floor(p.stage/3)*ch;g.save();g.translate(0,-67+Math.sin(t*1.4)*.6);for(const side of [-1,1]){g.save();g.rotate(side*Math.sin(t*1.35)*p.flap);g.scale(1+Math.sin(t*1.35)*.022,1);g.globalCompositeOperation='source-over';g.globalAlpha=.96;g.drawImage(im,sx+(side>0?cw/2:0),sy,cw/2,ch,side>0?0:-p.width/2,-p.height*.56,p.width/2,p.height);g.globalCompositeOperation='screen';for(let n=0;n<p.glints;n++){const q=(t*.10+n*.618)%1,x=side*(18+q*p.width*.35),y=-p.height*.28-Math.sin(q*Math.PI)*p.height*.24;glint(g,x,y,n%2?1.2:2.1,accent,Math.sin(q*Math.PI)*.65);}g.restore();}g.restore();return true;}
export function presenceIcon(style){const color=style.color||'#9de9ff',shape=style.theme==='prism'?'<path d="M20 4L32 20 20 36 8 20Z M20 4V36M8 20H32"/>':style.theme==='flame'?'<path d="M20 4Q30 16 29 25 27 35 19 35 8 34 9 25 10 16 14 13 13 23 18 25 22 20 20 4Z"/>':style.theme==='seraph'?'<path d="M18 30Q3 29 5 10 10 20 18 20M22 30Q37 29 35 10 30 20 22 20M12 13L17 19M28 13L23 19"/>':'<path d="M12 35C30 24 6 16 24 5M20 35C35 24 17 14 30 6M8 27C1 16 19 13 12 5"/>';return `<svg viewBox="0 0 40 40" aria-hidden="true"><g fill="none" stroke="${color}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${shape}</g></svg>`;}
